<script setup>
import {ref,computed} from 'vue';import {api} from '../store';
const resultado=ref(null),error=ref(''),ocupado=ref(false),csv=ref(''),nombre=ref(''),filtro=ref('');
const ejemplo='estudiante,curso,nota,asistencia\nAna,Base de Datos,16,90\nAna,Programación,18,95\nLuis,Base de Datos,9,65\nLuis,Programación,10,70\nMaría,Base de Datos,13,82\nMaría,Programación,14,88\nCarlos,Base de Datos,15,92\nCarlos,Programación,17,94\nLucía,Base de Datos,11,72\nLucía,Programación,12,78\nDiego,Base de Datos,8,90\nDiego,Programación,10,85';
const detalle=computed(()=>resultado.value?.detalle.filter(e=>!filtro.value||e.riesgo===filtro.value)||[]);
async function seleccionar(e){const f=e.target.files[0];if(!f)return;error.value='';if(f.size>900000){error.value='Archivo demasiado grande (máximo 900 KB).';return}csv.value=await f.text();nombre.value=f.name;resultado.value=null}
async function analizar(){error.value='';ocupado.value=true;try{resultado.value=await api('/analisis','POST',{csv:csv.value});filtro.value=''}catch(e){error.value=e.message}finally{ocupado.value=false}}
function demo(){csv.value=ejemplo;nombre.value='ejemplo.csv';analizar()}
function descargar(){const url=URL.createObjectURL(new Blob([ejemplo],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ejemplo.csv';a.click();URL.revokeObjectURL(url)}
</script>
<template><div class="page-heading"><div><div class="eyebrow">ANÁLISIS MULTIPARADIGMA</div><h2>Rendimiento académico</h2><p>Procesamiento de datos, estadísticas y alertas de riesgo académico.</p></div></div><div class="card p-4 mb-4"><h5>Importar registros académicos</h5><p class="text-secondary">CSV con columnas estudiante, curso, nota (0–20) y asistencia (0–100%). Utiliza identificadores ficticios para la exposición.</p><input class="form-control mb-3" type="file" accept=".csv,text/csv" @change="seleccionar"><div class="d-flex gap-2 flex-wrap"><button class="btn btn-primary" :disabled="!csv||ocupado" @click="analizar">Analizar CSV</button><button class="btn btn-outline-primary" :disabled="ocupado" @click="demo">Analizar datos de ejemplo</button><button class="btn btn-outline-secondary" @click="descargar">Descargar CSV de prueba</button></div><p v-if="nombre" class="small mt-2 mb-0">{{nombre}}</p></div><div v-if="ocupado" class="alert alert-info">Procesando datos con Python, pandas y NumPy…</div><div v-if="error" class="alert alert-danger">{{error}}</div><template v-if="resultado"><div class="row g-3 mb-4"><div class="col-6 col-xl-3" v-for="m in [['Estudiantes',resultado.estudiantes],['Promedio',resultado.promedio],['Registros aprobados',resultado.aprobacion+'%'],['Riesgo alto',resultado.riesgos.Alto]]" :key="m[0]"><div class="card metric"><span>{{m[0]}}</span><strong>{{m[1]}}</strong></div></div></div><div class="row g-3 mb-4"><div class="col-lg-6"><div class="card p-4 h-100"><h5>Promedio por curso (0–20)</h5><div v-for="c in resultado.cursos" :key="c.curso" class="mb-3"><div class="d-flex justify-content-between"><span>{{c.curso}}</span><strong>{{c.promedio}}</strong></div><div class="progress"><div class="progress-bar" :style="{width:c.promedio*5+'%'}"></div></div></div><hr><p>Mediana: {{resultado.mediana}} · Desviación estándar poblacional: {{resultado.desviacion}}</p><p class="mb-0">Mínimo: {{resultado.minimo}} · Máximo: {{resultado.maximo}} · Registros: {{resultado.registros}}</p></div></div><div class="col-lg-6"><div class="card p-4 h-100"><h5>Distribución de riesgo</h5><div v-for="n in ['Alto','Medio','Bajo']" :key="n" class="mb-3"><div class="d-flex justify-content-between"><span>{{n}}</span><strong>{{resultado.riesgos[n]}}</strong></div><div class="progress"><div :class="['progress-bar',n==='Alto'?'bg-danger':n==='Medio'?'bg-warning':'bg-success']" :style="{width:resultado.riesgos[n]/resultado.estudiantes*100+'%'}"></div></div></div><small class="text-secondary">Reglas ilustrativas: promedio menor a 11 = alto; asistencia menor a 75% o promedio menor a 14 = medio; demás = bajo.</small></div></div></div><div class="card p-4"><div class="panel-heading"><h5>Diagnóstico por estudiante</h5><select class="form-select w-auto" v-model="filtro"><option value="">Todos los riesgos</option><option>Alto</option><option>Medio</option><option>Bajo</option></select></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Estudiante</th><th>Promedio</th><th>Asistencia %</th><th>Riesgo</th><th>Recomendación</th></tr></thead><tbody><tr v-for="e in detalle" :key="e.estudiante"><td>{{e.estudiante}}</td><td>{{e.nota}}</td><td>{{e.asistencia}}</td><td><span :class="['badge',e.riesgo==='Alto'?'text-bg-danger':e.riesgo==='Medio'?'text-bg-warning':'text-bg-success']">{{e.riesgo}}</span></td><td>{{e.recomendacion}}</td></tr></tbody></table></div></div></template></template>